mapper.select:
SELECT id, user_id AS userId, item_id AS itemId, deleted, created_at AS createdAt, updated_at AS updatedAt
FROM user_item_favorites
WHERE user_id = #{userId}
  AND item_id = #{itemId}
LIMIT 1

mapper.update:
UPDATE user_item_favorites
SET deleted = 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND item_id = #{itemId}
  AND deleted = 0
